```python
def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [list(row) for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                has_left = any(grid[r][lc] == 2 for lc in range(c))
                has_right = any(grid[r][rc] == 2 for rc in range(c + 1, cols))
                has_above = any(grid[ar][c] == 2 for ar in range(r))
                has_below = any(grid[br][c] == 2 for br in range(r + 1, rows))

                if (has_left and has_right) or (has_above and has_below):
                    result[r][c] = 3

    return result
